                    "sql": "CREATE OR REPLACE TABLE SNITCH_DB.MAPLEMONK.FINAL_ESHIP_TRACKING AS WITH converted AS ( SELECT e.order_status AS eship_status, UPPER(t.value:invoice_number::string) AS unique_order_id, UPPER(e.details:tag::STRING) AS status, UPPER(e.slug) AS courier_partner, UPPER(e.customer_referenc) AS combined_order_id, e.details:pod_link::STRING AS pod_link, e.is_reverse::BOOLEAN AS is_reverse, CONVERT_TIMEZONE( \'UTC\', \'Asia/Kolkata\', TO_TIMESTAMP_NTZ(SUBSTRING(e.date::STRING, 6, 20), \'DD MON YYYY HH24:MI:SS\') ) AS logistics_created_timestamp, TO_TIMESTAMP_NTZ( SUBSTRING(e.details:checkpoints[0]:\"date\"::STRING, 6, 20), \'DD MON YYYY HH24:MI:SS\' ) AS last_updated_timestamp, CONVERT_TIMEZONE( \'Asia/Kolkata\', \'UTC\',TO_TIMESTAMP_NTZ( TO_TIMESTAMP_TZ(e.details:delivery_date::STRING, \'DY, DD MON YYYY HH24:MI:SS TZD\') )) AS logistics_delivery_timestamp, ( TO_TIMESTAMP_NTZ( TO_TIMESTAMP_TZ(e.details:expected_delivery_date::STRING, \'DY, DD MON YYYY HH24:MI:SS TZD\') ) - INTERVAL \'11 hours\' ) AS logistics_expected_delivery_date, e.pickup_attempts::NUMBER AS pickup_attempts, e.pickup_meta:pickup_request::BOOLEAN AS pickup_request, e.delivery_attempts::NUMBER AS delivery_attempts, CASE WHEN NULLIF(e.first_ofd_date,\'\') ILIKE \'%GMT%\' THEN TO_TIMESTAMP_NTZ( TO_TIMESTAMP_TZ(e.first_ofd_date::STRING, \'DY, DD MON YYYY HH24:MI:SS TZD\') ) ELSE TO_TIMESTAMP_NTZ(NULLIF(e.first_ofd_date,\'\')) END AS first_ofd_date, CASE WHEN NULLIF(e.latest_ofd_date,\'\') ILIKE \'%GMT%\' THEN TO_TIMESTAMP_NTZ( TO_TIMESTAMP_TZ(e.latest_ofd_date::STRING, \'DY, DD MON YYYY HH24:MI:SS TZD\') ) ELSE TO_TIMESTAMP_NTZ(NULLIF(e.latest_ofd_date,\'\')) END AS latest_ofd_date, CASE WHEN LOWER(e.slug) LIKE \'%gati%\' THEN TRY_TO_TIMESTAMP_NTZ( SUBSTRING( e.details:checkpoints[array_size(e.details:checkpoints)-1]:date::STRING, 6, 20 ), \'DD MON YYYY HH24:MI:SS\' ) WHEN TRY_TO_TIMESTAMP_NTZ( e.tracking_pick_date, \'YYYY-MM-DD\"T\"HH24:MI:SS\' ) IS NOT NULL THEN TRY_TO_TIMESTAMP_N