arehouse_sla_performance WHERE marketplace_mapped = \'STORE\' ) SELECT * FROM test WHERE rn = 1 ), final1 AS ( SELECT f.*, uc.order_timestamp FROM final f LEFT JOIN uc ON f.order_no = uc.order_name ), calc AS ( SELECT f1.*, CASE WHEN is_reverse THEN DATEADD(\'day\', 2, logistics_created_timestamp) ELSE CASE WHEN EXTRACT(hour FROM logistics_created_timestamp) < 18 THEN DATE_TRUNC(\'day\', logistics_created_timestamp) + INTERVAL \'21 hour\' ELSE DATE_TRUNC(\'day\', logistics_created_timestamp + INTERVAL \'1 day\') + INTERVAL \'21 hour\' END END AS pickup_tat, CASE WHEN tracking_pick_date IS NULL THEN NULL WHEN is_reverse THEN CASE WHEN UPPER(receiver_company_name) LIKE \'%WH - NORTH%\' THEN DATE_TRUNC(\'day\', DATEADD(\'day\', COALESCE( (SELECT tat_north_wh FROM store_tat WHERE store_name = UPPER(from_party)), 3 ), tracking_pick_date)) + INTERVAL \'23 hour\' WHEN UPPER(receiver_company_name) LIKE \'%WH - YELHANKA%\' OR UPPER(receiver_company_name) LIKE \'%WH -YELHANKA%\' OR UPPER(receiver_company_name) LIKE \'%YELHANKA 2%\' THEN DATE_TRUNC(\'day\', DATEADD(\'day\', COALESCE( (SELECT tat_south_wh FROM store_tat WHERE store_name = UPPER(from_party)), 3 ), tracking_pick_date)) + INTERVAL \'23 hour\' ELSE DATE_TRUNC(\'day\', DATEADD(\'day\', CASE WHEN zone = \'SOUTH\' THEN 2 WHEN zone = \'WEST\' THEN 3 WHEN zone = \'NORTH\' THEN 4 WHEN zone = \'EAST\' THEN 5 ELSE 3 END, tracking_pick_date)) + INTERVAL \'23 hour\' END ELSE CASE WHEN LOWER(courier_partner) LIKE \'%porter%\' OR LOWER(courier_partner) LIKE \'%self%\' THEN CASE WHEN receiver_city IN (\'BANGALORE\',\'BENGALURU\') THEN DATE_TRUNC(\'day\', tracking_pick_date) + INTERVAL \'23 hour\' ELSE NULL END WHEN LOWER(courier_partner) LIKE \'%movemate%\' OR LOWER(courier_partner) LIKE \'%mmn%\' THEN CASE WHEN receiver_state = \'KARNATAKA\' THEN DATE_TRUNC(\'day\', tracking_pick_date + INTERVAL \'1 day\') + INTERVAL \'23 hour\' ELSE NULL END ELSE NULL END END AS delivery_tat, CASE WHEN is_reverse THEN CASE WHEN tracking_pick_date IS NULL AND DATEADD(\'day\', 2, logistics_created_timestamp) < CURRENT_TIMESTAMP THEN \'BREACHED-PENDING FOR PROCESS\' WHEN tracking_pick_date IS NULL THEN \'FUTURE SLA\' WHEN DATEDIFF(DAY, logistics_created_timestamp, tracking_pick_date) <= 2 THEN \'WITHIN_SLA\' ELSE \'BREACHED\' END ELSE CASE WHEN tracking_pick_date IS NULL AND pickup_tat IS NULL THEN \'FUTURE SLA\' WHEN tracking_pick_date IS NULL AND pickup_tat < CURRENT_TIMESTAMP THEN \'BREACHED-PENDING FOR PROCESS\' WHEN tracking_pick_date IS NULL AND pickup_tat >= CURRENT_TIMESTAMP THEN \'FUTURE SLA\' WHEN tracking_pick_date > pickup_tat THEN \'BREACHED\' ELSE \'WITHIN_SLA\' END END AS pickup_sla, CASE WHEN logistics_delivery_timestamp IS NULL AND delivery_tat IS NULL THEN \'FUTURE SLA\' WHEN logistics_delivery_timestamp IS NULL AND delivery_tat < CURRENT_TIMESTAMP THEN \'BREACHED-PENDING FOR PROCESS\' WHEN logistics_delivery_timestamp IS NULL AND delivery_tat >= CURRENT_TIMESTAMP THEN \'FUTURE SLA\' WHEN logistics_delivery_timestamp > delivery_tat THEN \'BREACHED\' ELSE \'WITHIN_SLA\' END AS delivery_sla, CASE WHEN logistics_delivery_timestamp IS NOT NULL AND logistics_expected_delivery_date IS NOT NULL AND logistics_delivery_timestamp <= logistics_expected_delivery_date THEN \'WITHIN_SLA\' WHEN logistics_delivery_timestamp IS NOT NULL AND logistics_expected_delivery_date IS NOT NULL AND logistics_delivery_timestamp > logistics_expected_delivery_date THEN \'BREACHED\' WHEN logistics_delivery_timestamp IS NULL AND logistics_expected_delivery_date IS NOT NULL AND logistics_expected_delivery_date > CURRENT_TIMESTAMP THEN \'FUTURE SLA\' WHEN logistics_delivery_timestamp IS NULL AND logistics_expected_delivery_date IS NOT NULL AND logistics_expected_delivery_date <= CURRENT_TIMESTAMP THEN \'BREACHED-PENDING FOR PROCESS\' ELSE NULL END AS logistics_delivery_sla, CASE WHEN tracking_number IN ( \'53540504592\',\'53540504802\',\'53540504706\',\'53540503542\',\'53540504522\', \'53540505745\',\'53540503903\',\'5354